import{_ as e,c as r,o as t,ae as o}from"./chunks/framework.CHDT0Kbg.js";const u=JSON.parse('{"title":"隱私選擇","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/privacy-choices.md","filePath":"zh-TW/guide/privacy-choices.md","lastUpdated":1795170900000}'),i={name:"zh-TW/guide/privacy-choices.md"};function h(c,a,l,n,s,d){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="隱私選擇" tabindex="-1">隱私選擇 <a class="header-anchor" href="#隱私選擇" aria-label="Permalink to &quot;隱私選擇&quot;">​</a></h1><p>幾個簡單的方法，讓你自己掌控。</p><h2 id="無痕瀏覽" tabindex="-1">無痕瀏覽 <a class="header-anchor" href="#無痕瀏覽" aria-label="Permalink to &quot;無痕瀏覽&quot;">​</a></h2><p>使用無痕視窗（⌘⇧N）。它不會寫入歷史記錄或記住工作階段，關閉後分頁即消失。</p><h2 id="清除已存內容" tabindex="-1">清除已存內容 <a class="header-anchor" href="#清除已存內容" aria-label="Permalink to &quot;清除已存內容&quot;">​</a></h2><p>在設定的 Cookie 管理員裡刪除 Cookie 與網站資料。歷史記錄與下載記錄也可以在同一處清除。</p><h2 id="決定每個網站能做什麼" tabindex="-1">決定每個網站能做什麼 <a class="header-anchor" href="#決定每個網站能做什麼" aria-label="Permalink to &quot;決定每個網站能做什麼&quot;">​</a></h2><p>相機、麥克風與檔案權限按網站分別記住。在設定裡允許你信任的網站、拒絕其他網站。彈出式視窗只對你允許的網站開放。</p><h2 id="控制背景功能" tabindex="-1">控制背景功能 <a class="header-anchor" href="#控制背景功能" aria-label="Permalink to &quot;控制背景功能&quot;">​</a></h2><p>在設定裡隨時開關廣告攔截訂閱。關閉後不會拉取任何規則。</p><h2 id="選擇搜尋引擎" tabindex="-1">選擇搜尋引擎 <a class="header-anchor" href="#選擇搜尋引擎" aria-label="Permalink to &quot;選擇搜尋引擎&quot;">​</a></h2><p>在設定裡指定預設搜尋引擎，搜尋建議來自你選擇的引擎。</p><h2 id="有疑問" tabindex="-1">有疑問 <a class="header-anchor" href="#有疑問" aria-label="Permalink to &quot;有疑問&quot;">​</a></h2><p>想了解更多資料處理方式，請寫信到 <strong><a href="mailto:persim@w3cub.com" target="_blank" rel="noreferrer">persim@w3cub.com</a></strong>。</p>',14)])])}const _=e(i,[["render",h]]);export{u as __pageData,_ as default};
